From d4bad77b97dba7687e3625cef70d56c8a136059e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:16:13 +0100
Subject: [PATCH] applets/digital-clock: Skip NoDisplay helpers when picking
 the calendar app
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Only the preferred text/calendar handler was considered, so a hidden helper
like "KOrganizer View" on top either hid the "Add…" button or got launched
without a file. Use the most preferred suitable handler that isn't NoDisplay.

BUG: 507161
---
 .../digital-clock/plugin/applicationintegration.cpp  | 12 +++++-------
 1 file changed, 5 insertions(+), 7 deletions(-)

diff --git a/applets/digital-clock/plugin/applicationintegration.cpp b/applets/digital-clock/plugin/applicationintegration.cpp
index 8ed13e328b..42976bd31c 100644
--- a/applets/digital-clock/plugin/applicationintegration.cpp
+++ b/applets/digital-clock/plugin/applicationintegration.cpp
@@ -40,17 +40,15 @@ void ApplicationIntegration::launchCalendar() const

 void ApplicationIntegration::refresh()
 {
-    KService::Ptr newService = KApplicationTrader::preferredService(QStringLiteral("text/calendar"));
+    const KService::List services = KApplicationTrader::queryByMimeType(u"text/calendar"_s, [](const KService::Ptr &service) {
+        // This does deliberately not include inherited mime types, so that we only consider "real" calendar applications.
+        return !service->noDisplay() && service->mimeTypes().contains(u"text/calendar"_s);
+    });

     bool wasInstalled = calendarInstalled();
     QString oldName = calendarApplicationName();

-    // This does deliberately not include inherited mime types, so that we only consider "real" calendar applications.
-    if (newService && newService->mimeTypes().contains(u"text/calendar"_s)) {
-        m_calendarService = newService;
-    } else {
-        m_calendarService = nullptr;
-    }
+    m_calendarService = services.value(0);

     if (wasInstalled != calendarInstalled()) {
         Q_EMIT calendarInstalledChanged();
-- 
